decisions:
if (get("TF_GLM_ROCE_MULTI")) |v| {
    if (std.mem.eql(u8, v, "1")) s.roce_multi = true else if (std.mem.eql(u8, v, "0")) s.roce_multi = false else {
        problem.* = "TF_GLM_ROCE_MULTI: 0 or 1";
        return error.BadSetting;
    }
}
if (get("TF_ROCE")) |v| s.roce_wide = std.mem.eql(u8, v, "1");
// port note (af9777b49): upstream's CHUNK_SOLO (2048 or 4096) and the fork's busy step (4096 also sets
// TF_GLM_CHUNK's default rows) share the knob: 4096 turns both on, 2048 upstream's buffers alone.
if (get("TF_GLM_CHUNK_SOLO")) |v| {
    if (std.mem.eql(u8, v, "4096")) {
        s.solo = true;
        s.chunk = 2048;
    } else if (std.mem.eql(u8, v, "2048")) s.solo = true else {
        problem.* = "TF_GLM_CHUNK_SOLO: 2048 or 4096";
        return error.BadSetting;
    }
}
if (get("TF_GLM_CHUNK")) |v| {
    const rows = std.fmt.parseInt(u32, v, 10) catch 0;
    if (s.chunk == 0) {
        problem.* = "TF_GLM_CHUNK needs TF_GLM_CHUNK_SOLO=4096";
        return error.BadSetting;
    }
    if (rows != 2048 and rows != 1024) {
        problem.* = "TF_GLM_CHUNK: 2048 or 1024 (rows a prompt step takes beside a decoding stream)";
        return error.BadSetting;
    }
    s.chunk = rows;
}
s.l2pf = try l2pf.Options.read(get, problem);
if (get("TF_GLM_PROMPT_PAIR")) |v| {
    if (std.mem.eql(u8, v, "1")) s.pair = true else if (std.mem.eql(u8, v, "0")) s.pair = false else {
        problem.* = "TF_GLM_PROMPT_PAIR: 0 or 1";
        return error.BadSetting;
    }
}
